# Conduits: the only flows allowed between zones (default deny).
CONDUITS = {
    ("enterprise", "dmz"):   {"https/443"},           # staff read the replica historian
    ("ops", "dmz"):          {"historian-sync"},       # plant historian pushes out
    ("ops", "control"):      {"modbus/502"},           # HMI polls and writes the PLC
    ("dmz", "ops"):          {"rdp/3389 via jump"},    # remote support, MFA, time-limited
}
ZONE = {"10.0.1.20": "enterprise", "10.1.0.5": "dmz", "10.2.0.10": "ops",
        "10.2.0.11": "ops", "10.3.0.20": "control"}

def decide(src, dst, service):
    pair = (ZONE[src], ZONE[dst])
    if pair[0] == pair[1]:
        return "allow (same zone)"
    if service in CONDUITS.get(pair, set()):
        return "allow (conduit)"
    return "DENY and alert"

flows = [("10.2.0.10", "10.3.0.20", "modbus/502"),   # HMI to PLC
         ("10.0.1.20", "10.3.0.20", "modbus/502"),   # office laptop to PLC
         ("10.0.1.20", "10.1.0.5",  "https/443"),     # office to DMZ historian
         ("10.1.0.5",  "10.0.1.20", "smb/445")]       # DMZ to office share
for f in flows:
    print(f, decide(*f))

import hashlib

def manifest(blocks: dict) -> dict:
    """Hash every program block exported from a PLC."""
    return {name: hashlib.sha256(code).hexdigest()[:12] for name, code in blocks.items()}

def compare(golden: dict, current: dict) -> list:
    findings = []
    for name in sorted(golden.keys() | current.keys()):
        if name not in current:
            findings.append(f"{name}: missing from PLC")
        elif name not in golden:
            findings.append(f"{name}: NEW block, not in approved backup")
        elif golden[name] != current[name]:
            findings.append(f"{name}: CHANGED since approved backup")
    return findings or ["matches approved backup"]

# Approved backup taken after the last authorised change (stored offline).
golden = manifest({"OB1": b"call FC1; call FC2", "FC1": b"rungs 1-2", "FC2": b"rung 3"})
# Today's export, read with a clean laptop, not the plant's workstation.
today = manifest({"OB1": b"call FC9; call FC1; call FC2", "FC1": b"rungs 1-2",
                  "FC2": b"rung 3", "FC9": b"unknown logic"})
for line in compare(golden, today):
    print(line)

# Approved windows when a safety controller may be in PROGRAM mode.
WINDOWS = {"SIS-1": [("2026-03-02 08:00", "2026-03-02 12:00")]}

def in_window(ctrl, when):
    for start, end in WINDOWS.get(ctrl, []):
        if start <= when <= end:          # ISO strings sort like times
            return True
    return False

# Daily key-position readings: from a walk-down or the controller's diagnostics.
readings = [
    ("SIS-1", "2026-03-02 09:15", "PROGRAM"),
    ("SIS-1", "2026-03-03 09:00", "PROGRAM"),   # left in PROGRAM after the work
    ("SIS-2", "2026-03-03 09:00", "RUN"),
]
for ctrl, when, key in readings:
    if key == "RUN":
        status = "ok"
    elif in_window(ctrl, when):
        status = "ok (approved change in progress)"
    else:
        status = "ALERT: key in PROGRAM outside an approved window"
    print(ctrl, when, key, "|", status)

