@load base/protocols/modbus
@load base/frameworks/notice

module ModbusWatch;

export {
    redef enum Notice::Type += { Unexpected_Write };
    # Hosts allowed to write: the HMI and the engineering workstation
    const writers: set[addr] = { 10.2.0.10, 10.2.0.30 } &redef;
    # Modbus function codes that change data in the device
    const write_fcs: set[count] = { 5, 6, 15, 16, 21, 22, 23 } &redef;
}

event modbus_message(c: connection, headers: ModbusHeaders, is_orig: bool)
    {
    if ( ! is_orig )
        return;          # requests only, not the PLC's replies
    if ( headers$function_code !in write_fcs )
        return;          # reads are normal
    if ( c$id$orig_h in writers )
        return;          # an approved writer
    NOTICE([$note=Unexpected_Write, $conn=c,
            $msg=fmt("Modbus write fc=%d from %s to %s",
                     headers$function_code, c$id$orig_h, c$id$resp_h),
            $identifier=cat(c$id$orig_h, c$id$resp_h)]);
    }
